    const parsedPrice = parseInt(consignForm.price, 10) || 120000;
    const parsedOriginalPrice = parseInt(consignForm.originalPrice, 10) || (parsedPrice * 2);
    const parsedRentPrice = (consignForm.listingType === 'rent' || consignForm.listingType === 'both')
      ? (parseInt(consignForm.rentPrice, 10) || 60000)
      : null;
    const parsedDeposit = (consignForm.listingType === 'rent' || consignForm.listingType === 'both')
