        batch: currentUser.isLoggedIn ? currentUser.batch : 'K61 FTU Hanoi',
        faculty: currentUser.isLoggedIn ? currentUser.faculty : 'Khoa Ngoại Thương',
        avatar: currentUser.isLoggedIn ? currentUser.avatar : 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=200&q=80',
